source('mp10_cellchat_high_definition_sensitivity_v1/scripts/common.R')
source(file.path(root,'scripts/recover_lr.R'))
ef<-fread(tb('native_effects_rankings.tsv.gz'));cm<-fread(tb('comparable_background_effects.tsv.gz'));foc<-fread(tb('focus_candidate_union.tsv'));sel<-fread(tb('focus_pathway_selection.tsv'));d<-fread(tb('specimen_quantiles_coverage.tsv'))
# C30 dataset coverage only (no dataset inference).
v<-fread(tb('membership/C30__ALL__H50.tsv.gz'));counts<-v[,.(n_cells=.N,n_specimens=uniqueN(sample_uid),n_recorded_patient_ids=uniqueN(patient_uid_recorded[!is.na(patient_uid_recorded)])),by=.(dataset,node)];grid<-CJ(dataset=sort(unique(d$dataset)),node=fread(tb('node_counts.tsv'))[,unique(node)]);counts<-merge(grid,counts,by=c('dataset','node'),all.x=TRUE);for(n in c('n_cells','n_specimens','n_recorded_patient_ids'))set(counts,which(is.na(counts[[n]])),n,0L);counts[,`:=`(cohort='C30',inferred=FALSE,above10=n_cells>10,above30=n_cells>30)];put(counts,'C30_dataset_node_coverage_only.tsv')
# All High-definition changes with fixed Low and native shared background.
a<-ef[scope=='ALL' & min_cells==10 & lr_domain=='fixed_full'];wide<-dcast(a,cohort+direction+target+metric+background_id~high,value.var=c('RR','E','H','L','r_B','RR_status','rank_W_or_R'))
wide[,pattern:=fcase(is.na(RR_H50)|is.na(RR_H10)|is.na(RR_H05),'at_least_one_ratio_undefined',RR_H50>1 & RR_H10<=1 & RR_H05<=1,'H50_only_relative_enhancement',RR_H50<=1 & (RR_H10>1|RR_H05>1),'tail_relative_enhancement_emerges',RR_H50>1 & RR_H10>1 & RR_H05>1,'all_three_relative_enhancement',RR_H50<=1 & RR_H10<=1 & RR_H05<=1,'none_relative_enhanced',default='mixed_direction')]
put(wide,'ALL_high_definition_changes.tsv')
# Dataset consistency is a descriptive sign count using each dataset vs ALL on the identical universe.
u<-cm[cohort=='C10' & min_cells==10 & lr_domain=='fixed_full' & grepl('^ALL_dataset_common:',comparison_context)];u[,dataset_comparison:=sub('ALL_dataset_common:','',comparison_context)];ds<-u[scope!='ALL'];all<-u[scope=='ALL'];join<-merge(ds,all[,.(dataset_comparison,high,direction,target,metric,background_id,ALL_RR=RR,ALL_E=E)],by=c('dataset_comparison','high','direction','target','metric','background_id'));join[,`:=`(defined_pair=is.finite(RR)&is.finite(ALL_RR),same_enrichment_side=ifelse(is.finite(RR)&is.finite(ALL_RR),sign(RR-1)==sign(ALL_RR-1),NA),dataset_positive=!is.na(RR)&RR>1)];put(join,'dataset_ALL_same_background_comparison.tsv.gz')
rep<-join[,.(n_datasets=.N,n_dataset_RR_defined=sum(is.finite(RR)),n_paired_defined=sum(defined_pair),n_dataset_RR_gt1=sum(dataset_positive),n_agree_with_matched_ALL=sum(same_enrichment_side,na.rm=TRUE),positive_datasets=paste(dataset_comparison[dataset_positive],collapse=';'),undefined_datasets=paste(dataset_comparison[!is.finite(RR)],collapse=';')),by=.(high,direction,target,metric)];put(rep,'dataset_direction_support.tsv')
# Cohort change and min filter check kept explicitly separate.
u<-cm[scope=='ALL' & min_cells==10 & lr_domain=='fixed_full' & comparison_context=='C10_C30_common'];co<-dcast(u,high+direction+target+metric+background_id~cohort,value.var=c('RR','E','H','L','r_B','RR_status'));co[,same_enrichment_side:=ifelse(is.finite(RR_C10)&is.finite(RR_C30),sign(RR_C10-1)==sign(RR_C30-1),NA)];put(co,'C10_C30_same_background_comparison.tsv')
# LR-domain sensitivity uses the same computed network, changing only the LR inclusion domain.
u<-ef[scope=='ALL' & min_cells==10];dom<-dcast(u,cohort+high+direction+target+metric+background_id~lr_domain,value.var=c('RR','E','H','L'));dom[,RR_difference:=RR_fixed_full-RR_legacy_1875_intersection];put(dom,'LR_domain_sensitivity.tsv')
# Focus LR decomposition: reconstruct exact-zero LR only inside frozen domain, preserve raw and supported separately.
rows<-list();k<-0L
for(hi in c('H50','H10','H05'))for(di in c('output','input'))for(ta in foc$target){id<-paste('C10','ALL',hi,sep='__');h<-recover_lr(id,di,ta,'High');l<-recover_lr(id,di,ta,'Low');stopifnot(identical(h$interaction_id,l$interaction_id));for(mt in c('W','R')){z<-ef[cohort=='C10' & scope=='ALL' & high==hi & min_cells==10 & lr_domain=='fixed_full' & direction==di & target==ta & metric==mt];stopifnot(nrow(z)==1);v<-h[,.(interaction_id,pathway_name,ligand,receptor,LR_order,computed)];v[,`:=`(cohort='C10',scope='ALL',high=hi,min_cells=10L,lr_domain='fixed_full',background_id=z$background_id,direction=di,target=ta,metric=mt,H_probability=h$probability,L_probability=l$probability,H_internal_P=h$internal_P,L_internal_P=l$internal_P,H_supported=h$supported,L_supported=l$supported,H_LR=if(mt=='R')h$probability else ifelse(h$supported,h$probability,0),L_LR=if(mt=='R')l$probability else ifelse(l$supported,l$probability,0),r_B=z$r_B)];v[,`:=`(E_LR=H_LR-r_B*L_LR,sender_H=if(di=='output')'Epi High'else ta,receiver_H=if(di=='output')ta else'Epi High',sender_L=if(di=='output')'Epi Low'else ta,receiver_L=if(di=='output')ta else'Epi Low')];k<-k+1L;rows[[k]]<-v}}
lr<-rbindlist(rows);put(lr,'focus_LR_background_contributions.tsv.gz');main<-lr[is.finite(E_LR)&E_LR>0][order(-E_LR),head(.SD,10),by=.(cohort,scope,high,min_cells,lr_domain,background_id,direction,target,metric)];put(main,'focus_top10_positive_LR_contributions.tsv.gz')
# Identifies targets lacking positive pathways without inventing entries.
g<-CJ(target=foc$target,direction=c('input','output'));ct<-sel[,.N,by=.(target,direction)];g<-merge(g,ct,by=c('target','direction'),all.x=TRUE);g[is.na(N),N:=0L];g[,reason:=ifelse(N>0,'selected_positive_H05_W_pathways','no_positive_H05_W_pathway')];put(g,'focus_pathway_availability.tsv')
cat('EVIDENCE DONE\n')
